import{_ as r,l as n,o as e,c as l,v as t,p as s,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"预测评估 Diebold–Mariano","description":"","frontmatter":{"title":"预测评估 Diebold–Mariano","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/forecast-evaluation-dm.md","filePath":"econ/forecast-evaluation-dm.md","lastUpdated":1789023840000}'),E={name:"econ/forecast-evaluation-dm.md"};function m(D,a,_,h,A,u){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="预测评估-diebold–mariano" tabindex="-1">预测评估 Diebold–Mariano <a class="header-anchor" href="#预测评估-diebold–mariano" aria-label="Permalink to &quot;预测评估 Diebold–Mariano&quot;">​</a></h1><div class="epigraph"><p>两个预报哪个更准，不是看谁的 $R^2$ 更大，而是对损失差做检验；样本内拟合优不能代替样本外，嵌套模型还要把参数不确定性算进去。</p><footer>—— Diebold and Mariano, Comparing Predictive Accuracy, JBES 1995；West, Asymptotic Inference about Predictive Ability, Econometrica 1996</footer></div><p><a href="/econ/auction-structural-estimation">上一课</a>用结构反演做反事实。本课换目标：预报。结构单元里预测评估是另一类「对」——对损失，不对因果。极大似然下一课收束估计原则；本课钉 Diebold–Mariano（DM）与样本外。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宏观、汇率、通胀：两个模型给出预报 \\(\\hat y_{t|t-1}^{(1)}\\)、\\(\\hat y_{t|t-1}^{(2)}\\)，损失 \\(L\\)（平方、绝对、不对称）。损失差 \\(d_t=L_t^{(1)}-L_t^{(2)}\\)。DM：对 \\(\\bar d\\) 做（HAC）\\(t\\) 检验，\\(\\mathbb{E}[d_t]=0\\) 为等精度。缺口不是再讲汇率之谜的经济学，而是：样本内 \\(R^2\\) 可以把过参数模型判赢；样本外才是预报。嵌套模型（小模型是大模型的特例）下 \\(d_t\\) 的渐近退化，Clark–West 一类修正，不能直接套标准 DM。</p><p><span class="marginnote">Meese–Rogoff 把随机游走当汇率预报的基准，后课开放宏观会回到「脱节」。本课只要求：比较必须相对一个损失与一个基准，而不是「我们的结构 \\(R^2\\) 高」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>滚动或扩展窗口出样本外预报。DM 统计量用 \\(d_t\\) 的长期方差（Newey–West）。损失与决策匹配：点预报用平方；区间用覆盖；密度用 log score。Giacomini–White 条件检验问的是「给定当前信息，哪个方法更好」，允许预报方法含估计误差，更贴实务。数据窥探：许多模型赛跑后最小的 DM \\(p\\) 要多重检验修正——接<a href="/econ/inference-robust-cluster">推断课</a>。</p>',8)),(e(),s(p,null,{default:o(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%8D%9F%E5%A4%B1%20L%22%5D%20--%3E%20D%5B%22%E6%8D%9F%E5%A4%B1%E5%B7%AE%20d_t%22%5D%0A%20%20D%20--%3E%20DM%5B%22DM%3A%20HAC%20t%22%5D%0A%20%20NEST%5B%22%E5%B5%8C%E5%A5%97%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20CW%5B%22Clark%E2%80%93West%20%E7%AD%89%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20IN%5B%22%E6%A0%B7%E6%9C%AC%E5%86%85%E6%8B%9F%E5%90%88%22%5D%20--%3E%20OVER%5B%22%E8%BF%87%E6%8B%9F%E5%90%88%2C%20%E4%B8%8D%E4%BB%A3%E6%9B%BF%E6%A0%B7%E6%9C%AC%E5%A4%96%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与因果：预报可以故意用「坏」的相关（如果相关稳定）。Lucas 仍然说规则一变相关可以垮；预报评估不宣称结构弹性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是损失差的均值是否为零。平方损失下这接近 MSE 比较。序列相关（重叠的多步预报）必须进 HAC，否则 \\(t\\) 膨胀。嵌套时大模型在原假设下只多噪声，MSE 差的期望是 \\(O(1/P)\\) 的负项（参数不确定性），朴素 DM 会偏向拒绝小模型——Clark–West 把这项加回来。</p><p>与结构估计：拍卖或 BLP 的样本内 GMM 目标小，不表示样本外份额预报赢。若目标是政策反事实，DM 不是主检验；若目标是央行短预报，DM 是主检验。两种「好」不要混。</p><p><span class="marginnote">West 1996 把估计参数的不确定性送进预测检验的渐近。窗口方案（滚动 / 扩展 / 固定）改变方差公式。报 DM 时要写窗口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重做 Meese–Rogoff 的表。不把 DM 用于截面因果的安慰剂（那是另一套随机化推断）。下一课 MLE 与贝叶斯：估计原则，可以服务结构也可以服务预报，但本课的损失是决策，不是似然本身（除非 log score）。量化栏的高频预报不在此写限价簿。</p><p>后课默认：比较预报用样本外损失差 + 合适的 DM / Clark–West / Giacomini–White；样本内 \\(R^2\\) 不够。嵌套与重叠多步要改方差。因果识别成功不等于预报赢，反过来也不等于。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DM 检验损失差均值为零；HAC 管重叠与相关。</li><li>样本外才是预报；样本内拟合会偏袒大模型。</li><li>嵌套模型用 Clark–West 一类，勿直接 DM。</li><li>损失要与决策匹配；规则改变仍可让精度垮。</li><li>出处：Diebold and Mariano, <em>JBES</em> 1995；West, <em>Econometrica</em> 1996；Clark and West；Giacomini and White。</li></ul>',10))])}const B=r(E,[["render",m]]);export{M as __pageData,B as default};
